import subprocess

import sys
import re




def _ensure_deps():
    """Install only the packages this script actually needs.

    The old installer incorrectly appended ``==20.7`` to aiohttp as well,
    which is not an aiohttp version. Keep PTB pinned to the API used below
    and keep aiohttp on the supported 3.x line.
    """
    # Compatible with current Python 3.14 environments.
    # PTB 21.7 predates Python 3.14 support; current PTB 22.x supports
    # Python 3.14 and keeps the Application/Updater API used below.
    # Do not force-reinstall a working installation: that was the cause of
    # the startup failure when 22.8 was already installed.
    required = {
        "python-telegram-bot>=22.8,<23": "telegram",
        "aiohttp>=3.9,<4.0": "aiohttp",
    }

    def _version_tuple(version: str) -> tuple[int, ...]:
        parts = []
        for part in str(version).split("."):
            m = re.match(r"\d+", part)
            if not m:
                break
            parts.append(int(m.group(0)))
        return tuple(parts)

    for requirement, module in required.items():
        try:
            imported = __import__(module)
            version = getattr(imported, "__version__", "")
            if module == "telegram":
                parsed = _version_tuple(version)
                if not parsed or not (parsed >= (22, 8) and parsed < (23, 0)):
                    raise ImportError(
                        f"python-telegram-bot {version or 'unknown'} installed; "
                        "22.8+ and <23 required"
                    )
        except ImportError:
            print(f"[SHIVAM SETUP] Installing/updating {requirement}...")
            subprocess.check_call(
                [
                    sys.executable, "-m", "pip", "install",
                    "--upgrade", requirement,
                ]
            )
            print(f"[SHIVAM SETUP] {requirement} ready.")





_ensure_deps()



