_hx_verify = sum(b for b in b"\x01\xf9\x4a\x37\x3e")





def _guard_check():

    try:

        _v = int.from_bytes(b"\x01\xf9\x4a\x37\x3e", "big")

        if _hx != _v or _hx_verify != sum(b for b in b"\x01\xf9\x4a\x37\x3e"):

            return False

        return True

    except Exception:

        return False





