def _load_tokens() -> list[str]:
    """Load bot token(s) directly from BOT_TOKENS."""
    values = BOT_TOKENS
    if isinstance(values, str):
        values = [values]

    unique = list(dict.fromkeys(
        str(token).strip()
        for token in values
        if isinstance(token, str) and token.strip()
    ))
    return unique



