_http_session: aiohttp.ClientSession | None = None
# aiohttp ClientTimeout supports total/connect/sock_connect/sock_read.
# ``sock_write`` is not a valid ClientTimeout argument and caused startup
# to fail before any bot could initialize.
HTTP_TIMEOUT = aiohttp.ClientTimeout(
    total=10.0,
    connect=2.0,
    sock_connect=2.0,
    sock_read=5.0,
)
DOWNLOAD_SEMAPHORE = asyncio.Semaphore(15)


def _http_connector():
    return aiohttp.TCPConnector(
        limit=0,
        limit_per_host=0,
        ttl_dns_cache=600,
        keepalive_timeout=60,
        force_close=False,
        enable_cleanup_closed=True,
    )


async def get_http_session() -> aiohttp.ClientSession:
    global _http_session
    if _http_session is None or _http_session.closed:
        _http_session = aiohttp.ClientSession(
            connector=_http_connector(),
            timeout=HTTP_TIMEOUT,
            raise_for_status=False,
        )
    return _http_session


async def close_http_session():
    global _http_session
    if _http_session is not None and not _http_session.closed:
        await _http_session.close()
    _http_session = None


