class NetworkErrorHandler:
    transient=(TimedOut,NetworkError,ConnectionError,OSError)
    def is_transient(self,exc): return isinstance(exc,self.transient)
class ConnectionManager:
    def __init__(self): self.online=True
    def mark_online(self): self.online=True
    def mark_offline(self): self.online=False
class CircuitBreaker:
    def __init__(self,failures=5,cooldown=0.01): self.failure_limit=max(1,int(failures)); self.cooldown=max(0.0,float(cooldown)); self.failures=0; self.opened_until=0.0
    def allow(self):
        if time.monotonic() >= self.opened_until:
            if self.opened_until: self.failures=0; self.opened_until=0.0
            return True
        return False
    def success(self): self.failures=0
    def failure(self):
        self.failures+=1
        if self.failures>=self.failure_limit: self.opened_until=time.monotonic()+self.cooldown
class FailureTracker:
    """Small in-memory failure tracker used by the recovery helpers.

    The script referenced ``FailureTracker`` before defining it, which caused
    a NameError during module initialization.  Keep this tracker lightweight
    and non-blocking so it does not change the existing request scheduling.
    """
    __slots__ = ("_failures",)

    def __init__(self):
        self._failures = {}

    def record_failure(self, key=0):
        count = self._failures.get(key, 0) + 1
        self._failures[key] = count
        return count

    def record_success(self, key=0):
        self._failures.pop(key, None)

    def get(self, key=0, default=0):
        return self._failures.get(key, default)

    def clear(self, key=None):
        if key is None:
            self._failures.clear()
        else:
            self._failures.pop(key, None)


class ErrorTracker(FailureTracker):
    pass


class ExceptionRecovery:
    """Non-blocking exception bookkeeping helper."""
    def __init__(self):
        self.last_error = None
        self.count = 0

    def record(self, exc):
        self.last_error = exc
        self.count += 1
        return self.count

    def reset(self):
        self.last_error = None
        self.count = 0


class RetryBudget:
    """Bounded retry counter; prevents unbounded retry loops."""
    def __init__(self, maximum=4):
        self.maximum = max(0, int(maximum))
        self.used = {}

    def consume(self, key=0):
        value = self.used.get(key, 0)
        if value >= self.maximum:
            return False
        self.used[key] = value + 1
        return True

    def remaining(self, key=0):
        return max(0, self.maximum - self.used.get(key, 0))

    def reset(self, key=None):
        if key is None:
            self.used.clear()
        else:
            self.used.pop(key, None)


class AdaptiveRateLimiter:
    """Per-key monotonic rate limiter that only adds waiting, never extra work."""
    def __init__(self, minimum_interval=0.05, maximum_interval=2.0):
        self.minimum_interval = max(0.0, float(minimum_interval))
        self.maximum_interval = max(self.minimum_interval, float(maximum_interval))
        self._intervals = {}
        self._last = {}
        self._locks = {}

    def interval(self, key=0):
        return self._intervals.get(key, self.minimum_interval)

    async def wait(self, key=0):
        lock = self._locks.setdefault(key, asyncio.Lock())
        async with lock:
            now = time.monotonic()
            delay = self.interval(key) - (now - self._last.get(key, 0.0))
            if delay > 0:
                await asyncio.sleep(delay)
            self._last[key] = time.monotonic()

    def success(self, key=0):
        self._intervals[key] = max(self.minimum_interval, self.interval(key) * 0.9)
        return self._intervals[key]

    def failure(self, key=0, retry_after=0.0):
        current = max(self.minimum_interval, self.interval(key))
        server_delay = max(0.0, float(retry_after or 0.0))
        self._intervals[key] = min(self.maximum_interval, max(current * 2.0, server_delay))
        return self._intervals[key]

    def reset(self, key=None):
        if key is None:
            self._intervals.clear(); self._last.clear()
        else:
            self._intervals.pop(key, None); self._last.pop(key, None)


class FloodBackoff:
    """Tracks Telegram flood/retry delays and exposes the required wait time."""
    def __init__(self, maximum=60.0):
        self.maximum = max(0.0, float(maximum))
        self._until = {}

    def set(self, key=0, seconds=0.0):
        self._until[key] = time.monotonic() + min(self.maximum, max(0.0, float(seconds)))

    def remaining(self, key=0):
        return max(0.0, self._until.get(key, 0.0) - time.monotonic())

    async def wait(self, key=0):
        delay = self.remaining(key)
        if delay > 0:
            await asyncio.sleep(delay)

    def clear(self, key=None):
        if key is None: self._until.clear()
        else: self._until.pop(key, None)


class RetryAfterHandler:
    """Normalizes Telegram RetryAfter values for the recovery layer."""
    @staticmethod
    def seconds(exc):
        try:
            return max(0.0, float(getattr(exc, "retry_after", 0.0)))
        except (TypeError, ValueError):
            return 0.0

    async def wait(self, exc):
        delay = self.seconds(exc)
        if delay > 0:
            await asyncio.sleep(delay)
        return delay


class RateLimitTracker:
    def __init__(self): self._values = {}
    def record(self, key=0, seconds=0.0): self._values[key] = max(0.0, float(seconds)); return self._values[key]
    def get(self, key=0): return self._values.get(key, 0.0)
    def clear(self, key=None):
        if key is None: self._values.clear()
        else: self._values.pop(key, None)


class CooldownManager:
    def __init__(self): self._until = {}
    def set(self, key=0, seconds=0.0): self._until[key] = time.monotonic() + max(0.0, float(seconds))
    def remaining(self, key=0): return max(0.0, self._until.get(key, 0.0) - time.monotonic())
    def active(self, key=0): return self.remaining(key) > 0
    def clear(self, key=None):
        if key is None: self._until.clear()
        else: self._until.pop(key, None)


