class BotTaskManager:
    def __init__(self): self._tasks = {}
    def add(self, bot, task):
        self._tasks.setdefault(bot, set()).add(task)
        task.add_done_callback(lambda t, b=bot: self._tasks.get(b, set()).discard(t))
        return task
    def get(self, bot): return {t for t in self._tasks.get(bot, set()) if not t.done()}
    async def cancel(self, bot):
        tasks = list(self.get(bot))
        for task in tasks: task.cancel()
        if tasks: await asyncio.gather(*tasks, return_exceptions=True)
        self._tasks.pop(bot, None)
    async def cancel_all(self):
        for bot in list(self._tasks): await self.cancel(bot)
