class TaskSupervisor(NonBlockingRunner):
    async def shutdown(self):
        tasks=list(self.tasks)
        for task in tasks:
            if not task.done(): task.cancel()
        if tasks: await asyncio.gather(*tasks,return_exceptions=True)
        self.tasks.clear()

class CacheManager:
    def __init__(self,maximum=1024): self.maximum=max(1,int(maximum)); self.data={}
    def get(self,key,default=None): return self.data.get(key,default)
    def set(self,key,value):
        if len(self.data)>=self.maximum and key not in self.data: self.data.pop(next(iter(self.data)))
        self.data[key]=value; return value
    def clear(self): self.data.clear()
