class Debouncer:
    def __init__(self): self._tasks={}
    def submit(self,key,coro_factory,delay=0.01):
        old=self._tasks.get(key)
        if old and not old.done(): old.cancel()
        async def delayed(): await asyncio.sleep(max(0.0,float(delay))); return await coro_factory()
        task=asyncio.create_task(delayed()); self._tasks[key]=task; return task
class Throttler:
    def __init__(self,interval=0.01): self.interval=max(0.0,float(interval)); self._last={}; self._locks={}
    async def wait(self,key=0):
        lock=self._locks.setdefault(key,asyncio.Lock())
        async with lock:
            remaining=self.interval-(time.monotonic()-self._last.get(key,0.0))
            if remaining>0: await asyncio.sleep(remaining)
            self._last[key]=time.monotonic()

