_LOOP_TEXT_CACHE = {}


def _prepared_loop_texts(texts):
    """Cache immutable, non-empty loop text tuples to avoid per-cycle allocations."""
    key = id(texts)
    cached = _LOOP_TEXT_CACHE.get(key)
    if cached is None:
        cached = tuple(t for t in texts if isinstance(t, str) and t.strip())
        _LOOP_TEXT_CACHE[key] = cached
    return cached



