#              FAST RECOVERY ENGINE
# ═══════════════════════════════════════════════

class FastRecoveryEngine:
    """Fast local recovery for transient transport failures.

    Telegram RetryAfter/FloodWait remains authoritative; this helper never
    shortens a server-provided cooldown.
    """
    __slots__ = ("base", "cap")

    def __init__(self, base=0.01, cap=2.0):
        self.base = max(0.0, float(base))
        self.cap = max(self.base, float(cap))

    def delay(self, failures: int) -> float:
        failures = max(0, int(failures))
        return min(self.cap, self.base * (2 ** max(0, failures - 1)))

    def reset(self):
        return 0

    async def recover(self, failures: int = 1):
        delay = self.delay(failures)
        if delay > 0:
            await asyncio.sleep(delay)
        else:
            await asyncio.sleep(0)


class InstantFireEngine:
    """Low-overhead coroutine scheduler with no artificial delay."""
    __slots__ = ("yield_delay",)

    def __init__(self, yield_delay=0.0):
        self.yield_delay = max(0.0, float(yield_delay))

    async def fire(self, coro):
        if self.yield_delay > 0:
            await asyncio.sleep(self.yield_delay)
        return await coro


_FAST_RECOVERY = FastRecoveryEngine(base=0.01, cap=0.01)
_INSTANT_FIRE = InstantFireEngine()



class BotFloodTracker:
    """Per-bot cooldown/failure tracker using monotonic time. Optimized for speed."""
    __slots__ = ("_until", "_failures")

    def __init__(self):
        self._until = {}
        self._failures = {}

    def ready(self, bot_index: int) -> bool:
        return time.monotonic() >= self._until.get(bot_index, 0.0)

    def remaining(self, bot_index: int) -> float:
        return max(0.0, self._until.get(bot_index, 0.0) - time.monotonic())

    def cooldown(self, bot_index: int, seconds: float) -> float:
        seconds = max(0.0, min(float(seconds), 3600.0))
        until = time.monotonic() + seconds
        current = self._until.get(bot_index, 0.0)
        if until > current:
            self._until[bot_index] = until
        return seconds

    def record_success(self, bot_index: int) -> None:
        self._failures.pop(bot_index, None)

    def record_failure(self, bot_index: int, base: float = 0.10, maximum: float = 3.0) -> float:
        """Exponential backoff with tighter bounds for better performance."""
        failures = self._failures.get(bot_index, 0) + 1
        self._failures[bot_index] = min(failures, 10)
        wait = min(float(maximum), float(base) * (2 ** min(failures - 1, 4)))
        self.cooldown(bot_index, wait)
        return wait


class HyperRateLimiter:
    """Per-bot smooth async request scheduler optimized for 10 concurrent workers.
    
    Guarantees 10 workers stay active per bot. Telegram server limits are never
    bypassed. All waiting happens OUTSIDE the per-bot lock to prevent serialization.
    """

    __slots__ = (
        "tracker", "_locks", "_next_at", "_last_grant",
        "min_interval"
    )

    def __init__(self, tracker=None, min_interval: float = 0.05):
        self.tracker = tracker or BotFloodTracker()
        self._locks = {}
        self._next_at = {}
        self._last_grant = {}
        self.min_interval = max(0.01, float(min_interval))

    def _lock(self, bot_index: int):
        lock = self._locks.get(bot_index)
        if lock is None:
            lock = asyncio.Lock()
            self._locks[bot_index] = lock
        return lock

    async def wait(self, bot_index: int) -> None:
        """Fast path: check ready status with minimal overhead."""
        remaining = self.tracker.remaining(bot_index)
        if remaining > 0:
            await asyncio.sleep(min(remaining, 0.10))

    async def reserve(self, bot_index: int) -> None:
        """Reserve a request slot. Never sleeps while holding lock."""
        while True:
            cooldown = self.tracker.remaining(bot_index)
            if cooldown <= 0:
                break
            await asyncio.sleep(min(cooldown, 0.10))

        async with self._lock(bot_index):
            cooldown = self.tracker.remaining(bot_index)
            if cooldown > 0:
                pass
            else:
                now = time.monotonic()
                previous = self._next_at.get(bot_index, now)
                slot = max(now, previous)
                self._next_at[bot_index] = slot + self.min_interval
                self._last_grant[bot_index] = now
                wait_for = slot - now
                if wait_for > 0.001:
                    await asyncio.sleep(wait_for)
                return

        await asyncio.sleep(min(cooldown, 0.10))

    async def run(self, bot_index: int, operation, *args, **kwargs):
        """Execute operation with rate limiting and error handling."""
        await self.reserve(bot_index)
        try:
            result = await operation(*args, **kwargs)
        except asyncio.CancelledError:
            raise
        except RetryAfter as exc:
            retry = max(0.0, float(exc.retry_after))
            self.tracker.cooldown(bot_index, retry)
            async with self._lock(bot_index):
                self._next_at[bot_index] = max(
                    self._next_at.get(bot_index, 0.0),
                    time.monotonic() + retry
                )
            raise
        except (TimedOut, NetworkError, ConnectionError, OSError, aiohttp.ClientError):
            self.tracker.record_failure(bot_index)
            raise
        else:
            self.tracker.record_success(bot_index)
            return result


_BOT_FLOOD_TRACKER = BotFloodTracker()
_HYPER_RATE_LIMITER = HyperRateLimiter(_BOT_FLOOD_TRACKER, min_interval=0.05)


def _smoothsas_engine(delay_seconds: float, *, minimum: float = 0.01, maximum: float = 2.0) -> float:
    try:
        value = float(delay_seconds)
    except (TypeError, ValueError):
        value = minimum
    if value != value or value < minimum:
        return minimum
    return min(value, maximum)


async def _hyperfire_engine(coroutines, *, concurrency: int = 32):
    """Bounded async fan-out for independent operations; no rate-limit bypass."""
    jobs = list(coroutines)
    if not jobs:
        return []
    semaphore = asyncio.Semaphore(max(1, int(concurrency)))

    async def _runner(coro):
        async with semaphore:
            return await coro

    return await asyncio.gather(*(_runner(c) for c in jobs), return_exceptions=True)


async def _fast_http_set_title(bot, chat_id: int, text: str):
    token = getattr(bot, "token", None)
    if not token:
        raise RuntimeError("bot token unavailable")
    session = await get_http_session()
    url = f"https://api.telegram.org/bot{token}/setChatTitle"
    async with session.post(url, data={"chat_id": chat_id, "title": str(text)[:128]}) as response:
        if response.status == 429:
            try:
                payload = await response.json(content_type=None)
                retry_after = float(payload.get("parameters", {}).get("retry_after", 1.0))
            except Exception:
                retry_after = 1.0
            raise RetryAfter(retry_after)
        if response.status >= 400:
            try:
                payload = await response.json(content_type=None)
                description = payload.get("description", f"HTTP {response.status}")
            except Exception:
                description = f"HTTP {response.status}"
            raise RuntimeError(description)
        return True


async def fast_set_chat_title(bot, chat_id: int, text: str, bot_index: int = -1) -> bool:
    """Low-overhead title update using one reusable HTTP session.

    Telegram RetryAfter values are always honored; this helper does not bypass
    server-side flood/rate limits and falls back to python-telegram-bot on
    non-rate-limit HTTP failures.
    """
    async def _operation():
        return await _fast_http_set_title(bot, chat_id, text)

    try:
        if bot_index >= 0:
            return bool(await _HYPER_RATE_LIMITER.run(bot_index, _operation))
        return bool(await _operation())
    except asyncio.CancelledError:
        raise
    except RetryAfter as exc:
        if bot_index >= 0:
            _bot_cooldown_set(bot_index, exc.retry_after)
        return False
    except (TimedOut, NetworkError, ConnectionError, OSError, aiohttp.ClientError):
        try:
            await bot.set_chat_title(chat_id, text)
            return True
        except RetryAfter as exc:
            if bot_index >= 0:
                _bot_cooldown_set(bot_index, exc.retry_after)
            return False
        except Exception:
            return False
    except Exception as exc:
        err = str(exc).lower()
        if ("flood" in err or "too many" in err or "retry after" in err) and bot_index >= 0:
            # Unknown HTTP-layer flood errors get a conservative cooldown;
            # explicit RetryAfter exceptions are handled above with the exact
            # server-provided value.
            _bot_cooldown_set(bot_index, max(1.0, _BOT_FLOOD_TRACKER.remaining(bot_index)))
            return False
        try:
            await bot.set_chat_title(chat_id, text)
            return True
        except RetryAfter as retry_exc:
            if bot_index >= 0:
                _bot_cooldown_set(bot_index, retry_exc.retry_after)
            return False
        except Exception:
            return False


async def safe_send_message(bot, bot_index: int, **kwargs) -> bool:
    """Rate-limit-aware message sender.

    Telegram RetryAfter is authoritative: the affected bot is cooled down
    for the exact server-provided duration and the loop remains alive.
    """
    try:
        return bool(await _HYPER_RATE_LIMITER.run(
            bot_index, lambda: bot.send_message(**kwargs)
        ))
    except asyncio.CancelledError:
        raise
    except RetryAfter as exc:
        _bot_cooldown_set(bot_index, exc.retry_after)
        return False
    except (TimedOut, NetworkError, ConnectionError, OSError, aiohttp.ClientError) as exc:
        wait = _BOT_FLOOD_TRACKER.record_failure(bot_index)
        await asyncio.sleep(min(wait, 0.05))
        return False
    except Exception as exc:
        message = str(exc).lower()
        if "flood" in message or "too many" in message or "retry after" in message:
            _bot_cooldown_set(bot_index, 1.0)
        return False


async def safe_set_title(bot, chat_id: int, text: str, bot_index: int = -1) -> bool:
    return await fast_set_chat_title(bot, chat_id, text, bot_index)


# ═══════════════════════════════════════════════

#              PER-BOT FLOOD COOLDOWN TRACKER

# ═══════════════════════════════════════════════

_bot_cooldowns: Dict[int, float] = {}   # runtime mirror: bot_index -> expiry timestamp

# Persistent per-bot cooldown storage. This survives restarts.
COOLDOWN_FILE = "cooldowns.json"
BOT_COOLDOWNS: Dict[int, float] = {}

def load_cooldowns():
    global BOT_COOLDOWNS
    if os.path.exists(COOLDOWN_FILE):
        try:
            with open(COOLDOWN_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                now = time.time()
                BOT_COOLDOWNS = {int(k): float(v) for k, v in data.items() if float(v) > now}
        except Exception:
            BOT_COOLDOWNS = {}
    else:
        BOT_COOLDOWNS = {}

def save_cooldowns():
    """Save active cooldowns to disk. Remove expired entries."""
    try:
        now = time.time()
        active = {str(k): v for k, v in BOT_COOLDOWNS.items() if v > now}
        if active:
            with open(COOLDOWN_FILE, "w", encoding="utf-8") as f:
                json.dump(active, f)
        elif os.path.exists(COOLDOWN_FILE):
            os.remove(COOLDOWN_FILE)
    except Exception:
        pass

def is_bot_ready(bot_idx: int) -> bool:
    return time.time() >= BOT_COOLDOWNS.get(bot_idx, 0)

def set_bot_cooldown(bot_idx: int, seconds: float):
    expiry = time.time() + max(0.5, min(float(seconds), 3600.0))
    BOT_COOLDOWNS[bot_idx] = expiry
    _bot_cooldowns[bot_idx] = expiry

load_cooldowns()

def _bot_ready(idx: int) -> bool:
    return is_bot_ready(idx)

def _bot_cooldown_set(idx: int, seconds: float):
    set_bot_cooldown(idx, seconds)



