#              NC BOT LOOP

# ═══════════════════════════════════════════════

async def _nc_bot_worker(bot, chat_id: int, base: str, active_texts: tuple, bot_index: int, state: dict):
    """Independent async worker for one bot. Always active, guaranteed to stay alive.
    
    Ten long-lived asyncio workers run per bot 24/7. HyperRateLimiter provides
    the single shared request cadence. Workers never serialize or deadlock.
    """
    failures = 0
    while True:
        try:
            # Fast local recovery: don't spin while this bot is in cooldown
            if not is_bot_ready(bot_index):
                remaining = max(0.01, BOT_COOLDOWNS.get(bot_index, 0.0) - time.time())
                await asyncio.sleep(min(remaining, 0.5))
                continue

            async with state["index_lock"]:
                pos = state["index"]
                state["index"] = pos + 1

            if active_texts:
                raw = active_texts[pos % len(active_texts)]
                text = raw.replace("{target}", base) if "{target}" in raw else f"{base} {raw}"
            else:
                text = f"{base} {NC_EMOJIS[pos % len(NC_EMOJIS)]}"

            # All workers use shared HyperRateLimiter - no extra serialization
            success = await safe_set_title(bot, chat_id, text, bot_index)
            if success:
                _last_set_title[chat_id] = text
                failures = 0
            else:
                failures += 1
            
            # Yield to event loop
            await asyncio.sleep(0)

        except asyncio.CancelledError:
            raise
        except Exception as e:
            failures += 1
            wait = min(0.2, 0.01 * (2 ** min(failures - 1, 4)))
            await asyncio.sleep(wait)


async def nc_bot_loop(bot, chat_id: int, base: str, texts: list, bot_index: int = 0):
    """Run exactly 10 persistent workers per bot with shared rate limiter.
    
    Loop never hangs or gets stuck. Workers are supervised independently.
    All 10 workers run 24/7 without serialization.
    """
    active_texts = _prepared_loop_texts(texts)
    state = {
        "index": bot_index,
        "index_lock": asyncio.Lock(),
    }

    def spawn(slot: int):
        return asyncio.create_task(
            _nc_bot_worker(bot, chat_id, base, active_texts, bot_index, state),
            name=f"nc-worker-{bot_index}-{slot}",
        )

    workers = {slot: spawn(slot) for slot in range(ASYNC_RUNNERS_PER_BOT)}
    worker_restart_count = defaultdict(int)
    
    try:
        # Supervise all workers independently - one exit never kills others
        # Loop uses timeout to prevent infinite hangs
        while True:
            done, pending = await asyncio.wait(
                tuple(workers.values()), 
                return_when=asyncio.FIRST_COMPLETED,
                timeout=5.0  # Prevent infinite hangs
            )
            
            # Restart any completed/failed workers
            for task in done:
                slot = next((k for k, v in workers.items() if v is task), None)
                if slot is None:
                    continue
                
                try:
                    exc = task.exception()
                    if exc is not None:
                        worker_restart_count[slot] += 1
                        if worker_restart_count[slot] <= 3:
                            print(f"[SHIVAM WARN] nc worker {bot_index}:{slot} restarted: {exc}")
                except asyncio.CancelledError:
                    raise
                finally:
                    workers[slot] = spawn(slot)
            
            # Yield to prevent event loop blocking
            await asyncio.sleep(0)
            
    except asyncio.CancelledError:
        # Graceful shutdown
        for task in workers.values():
            if not task.done():
                task.cancel()
        await asyncio.gather(*workers.values(), return_exceptions=True)
        raise
    finally:
        # Ensure all workers are cleaned up
        for task in workers.values():
            if not task.done():
                task.cancel()
        await asyncio.gather(*workers.values(), return_exceptions=True)

async def spam_loop(chat_id: int, texts: list, extra: str):

    while True:

        try:

            active_texts = [t for t in texts if t.strip()]

            if not active_texts:

                await asyncio.sleep(0.25)

                continue

            spam_text = random.choice(active_texts)

            if extra:

                spam_text = spam_text.replace("{target}", extra)



            async def _send(idx: int, b, t=spam_text):

                if not _bot_ready(idx):

                    return

                try:

                    await safe_send_message(b, idx, chat_id=chat_id, text=t)

                except RetryAfter as e:

                    _bot_cooldown_set(idx, e.retry_after)

                except asyncio.CancelledError:

                    raise

                except Exception:

                    pass



            await asyncio.gather(*[_send(i, b) for i, b in enumerate(bots)])

            await asyncio.sleep(delay)

        except asyncio.CancelledError:

            raise

        except Exception as e:

            print(f"[SHIVAM WARN] spam_loop error chat {chat_id}: {e}")



