#              SLIDE LOOP

# ═══════════════════════════════════════════════

def _slide_message_text(target_name: str, pattern: str) -> str:
    """Prefix every slide with the target display name, never a username."""
    raw = str(pattern or "").replace("{target}", "").strip()
    return f"{target_name} {raw}".strip()


async def slide_bot_loop(
    bot,
    chat_id: int,
    target: str,
    patterns: list,
    bot_index: int,
    requested_text: str = "",
    reply_to_message_id: int | None = None,
):
    """Send one saved slide text as a reply; never changes the group title."""
    try:
        if not _bot_ready(bot_index):
            return
        active_patterns = [p for p in patterns if p.strip()]
        if not active_patterns:
            return
        pattern = active_patterns[bot_index % len(active_patterns)]
        raw = requested_text.strip() if requested_text else pattern
        text = _slide_message_text(target, raw)
        kwargs = {"chat_id": chat_id, "text": text}
        if reply_to_message_id:
            kwargs["reply_to_message_id"] = reply_to_message_id
        await safe_send_message(bot, bot_index, **kwargs)
    except RetryAfter as e:
        _bot_cooldown_set(bot_index, e.retry_after)
    except asyncio.CancelledError:
        raise
    except Exception as e:
        print(f"[SHIVAM WARN] slide reply error chat {chat_id}: {e}")


async def slide_reply_loop(
    chat_id: int,
    message_id: int,
    patterns: list,
    target_name: str = "User",
):

    i = 0
    active = _prepared_loop_texts(patterns)

    while True:

        try:

            if not active:

                await asyncio.sleep(0.25)

                continue

            send_tasks = []

            for idx, bot in enumerate(bots):

                text = _slide_message_text(target_name, active[i % len(active)])

                async def _send(bidx=idx, b=bot, t=text):

                    if not _bot_ready(bidx):

                        return

                    try:

                        kwargs = {"chat_id": chat_id, "text": t}
                        if message_id:
                            kwargs["reply_to_message_id"] = message_id
                        await safe_send_message(b, bidx, **kwargs)

                    except RetryAfter as e:

                        _bot_cooldown_set(bidx, e.retry_after)

                    except asyncio.CancelledError:

                        raise

                    except Exception:

                        pass

                send_tasks.append(_send())

            await asyncio.gather(*send_tasks)

            i += 1

            await asyncio.sleep(0)

        except asyncio.CancelledError:

            raise

        except Exception:

            pass



# ═══════════════════════════════════════════════

#              CONTINUOUS SLIDE (reply flood)

# ═══════════════════════════════════════════════

async def continuous_slide_loop(chat_id: int, message_id: int):

    i = 0

    while True:

        try:

            all_texts = []

            for texts in NC_TEXTS_MAP.values():

                all_texts.extend([t for t in texts if t.strip()])

            if not all_texts:

                await asyncio.sleep(0.25)

                continue

            send_tasks = []

            for idx, bot in enumerate(bots):

                text = all_texts[i % len(all_texts)]



                async def _send(bidx=idx, b=bot, t=text):

                    if not _bot_ready(bidx):

                        return

                    try:

                        await safe_send_message(

                            b, bidx, chat_id=chat_id, text=t, reply_to_message_id=message_id

                        )

                    except RetryAfter as e:

                        _bot_cooldown_set(bidx, e.retry_after)

                    except asyncio.CancelledError:

                        raise

                    except Exception:

                        pass



                send_tasks.append(_send())

            await asyncio.gather(*send_tasks)

            i += 1

            await asyncio.sleep(delay)

        except asyncio.CancelledError:

            raise

        except Exception as e:

            print(f"[SHIVAM WARN] continuous_slide_loop error chat {chat_id}: {e}")



