#              PHOTO LOOP

# ═══════════════════════════════════════════════

PFP_URL_RE = re.compile(r"^https?://\S+$", re.IGNORECASE)


async def _download_pfp(url: str) -> bytes:
    def fetch() -> bytes:
        from urllib.request import Request, urlopen

        request = Request(url, headers={"User-Agent": "TelegramBot/1.0"})
        with urlopen(request, timeout=15) as response:
            data = response.read()
        if not data:
            raise ValueError("empty image response")
        return data

    return await asyncio.to_thread(fetch)


async def photo_loop(chat_id: int, fallback_bot=None):

    i = 0

    while True:

        try:
            if chat_id in pfp_loop_stopped:
                return

            store = pfp_urls.get(chat_id, [])

            if not store:

                await asyncio.sleep(0.2)

                continue

            url = store[i % len(store)]
            active_bots = []
            if fallback_bot is not None:
                active_bots.append(fallback_bot)
            for candidate in bots:
                if candidate is not None and all(candidate is not b for b in active_bots):
                    active_bots.append(candidate)
            try:
                if isinstance(url, str) and url.startswith("tgfile:"):
                    source_bot = fallback_bot or (
                        active_bots[0] if active_bots else None
                    )
                    if source_bot is None:
                        raise RuntimeError("no bot available for PFP upload")
                    telegram_file = await source_bot.get_file(url[7:])
                    data = bytes(await telegram_file.download_as_bytearray())
                else:
                    data = await _download_pfp(url)
            except Exception as exc:
                print(f"[SHIVAM WARN] PFP download failed for {url}: {exc}")
                i += 1
                await asyncio.sleep(0)
                continue



            async def _set(idx: int, b, d=data):

                if b is not fallback_bot and not _bot_ready(idx):

                    return

                try:

                    await b.set_chat_photo(
                        chat_id=chat_id,
                        photo=InputFile(io.BytesIO(d), filename="pfp.jpg"),
                    )

                except RetryAfter as e:

                    _bot_cooldown_set(idx, e.retry_after)

                except asyncio.CancelledError:

                    raise

                except Exception:

                    pass



            if chat_id in pfp_loop_stopped:
                return

            await asyncio.gather(
                *[_set(idx, b) for idx, b in enumerate(active_bots)]
            )

            i += 1

            await asyncio.sleep(_current_delay(chat_id))

        except asyncio.CancelledError:

            raise

        except Exception as e:

            print(f"[SHIVAM WARN] photo_loop error chat {chat_id}: {e}")

            await asyncio.sleep(0)



