# Media shown with the help/menu command.
# Put either an image URL or a direct video URL here.
MENU_PFP_URL = "https://files.catbox.moe/kxq735.jpg"
VIDEO_URL_RE = re.compile(r"\.(?:mp4|m4v|mov|webm)(?:[?#].*)?$", re.IGNORECASE)


async def _send_menu(update: Update):
    # Send the PFP/video and menu text together as ONE Telegram message.
    menu_text = get_menu_text()
    if not isinstance(menu_text, str) or not menu_text.strip():
        menu_text = "𝐒ʜɪ𝐕ᴀᴍ 𝐁ᴏᴛ 𝐌ᴇɴᴜ\n\nMenu is temporarily unavailable."

    media_url = str(MENU_PFP_URL or "").strip()
    if media_url:
        try:
            if VIDEO_URL_RE.search(media_url):
                await update.message.reply_video(video=media_url, caption=menu_text)
            else:
                await update.message.reply_photo(photo=media_url, caption=menu_text)
            return
        except Exception as exc:
            logging.warning("Menu media failed (%s); sending text menu.", exc)

    # Fallback only if the media URL fails.
    await update.message.reply_text(menu_text)


@only_owner
async def help_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _send_menu(update)


@only_owner
async def menu_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _send_menu(update)


