def _slide_target(update: Update, args: list[str]):
    reply = update.message.reply_to_message
    if reply and reply.from_user:
        user = reply.from_user
        display_name = " ".join(
            part for part in (user.first_name, user.last_name) if part
        ).strip() or str(user.id)
        return display_name, user.id, reply.message_id, " ".join(args).strip()
    if not args:
        return None, None, None, ""
    return args[0].lstrip("@"), None, update.message.message_id, " ".join(args[1:]).strip()


async def _send_slide_once(bot, chat_id: int, target_name: str, pattern: str, reply_to_id):
    """Send one slide from the bot that received the command/update."""
    bot_id = getattr(bot, "id", None)
    if bot_id is not None and bot_id in our_bot_ids:
        bot_index = next(
            (index for index, candidate in enumerate(bots) if candidate is bot),
            -1,
        )
        if bot_index >= 0 and not _bot_ready(bot_index):
            return
    kwargs = {
        "chat_id": chat_id,
        "text": _slide_message_text(target_name, pattern),
    }
    if reply_to_id:
        kwargs["reply_to_message_id"] = reply_to_id
    try:
        await safe_send_message(bot, bot_index, **kwargs)
    except RetryAfter as exc:
        if bot_id is not None:
            bot_index = next(
                (index for index, candidate in enumerate(bots) if candidate is bot),
                -1,
            )
            if bot_index >= 0:
                _bot_cooldown_set(bot_index, exc.retry_after)
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        print(f"[SHIVAM WARN] slide send error in chat {chat_id}: {exc}")


def _make_slide_cmd(slide_num: int):
    @only_owner
    async def slide_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        target, target_user_id, reply_to_id, requested_text = _slide_target(
            update, context.args
        )
        if not target:
            return await update.message.reply_text(
                f"Reply to a user and use /slide{slide_num}."
            )
        active_patterns = [p for p in SLIDE_PATTERNS_MAP[slide_num] if p.strip()]
        if not active_patterns:
            return await update.message.reply_text(
                f"Slide{slide_num} has no configured messages."
            )

        chat_id = update.message.chat_id
        patterns = [requested_text] if requested_text.strip() else active_patterns
        session_key = (
            slide_num,
            chat_id,
            target_user_id if target_user_id is not None else target.casefold(),
        )

        if slide_num in (1, 2):
            async with slide_session_lock:
                slide_one_shot_sessions[session_key] = {
                    "target_name": target,
                    "target_user_id": target_user_id,
                    "reply_to_id": reply_to_id,
                    "patterns": patterns,
                    "next_index": 1,
                    "last_message_id": None,
                    "sent_bot_ids": set(),
                }
            await _send_slide_once(
                context.bot,
                chat_id,
                target,
                patterns[0],
                reply_to_id,
            )
        else:
            # A command update is delivered to every bot application.  Only
            # the first handler creates the shared continuous task.
            async with slide_session_lock:
                command_key = (slide_num, chat_id, target_user_id or target.casefold())
                existing = slide_one_shot_sessions.get(command_key)
                already_started = bool(
                    existing and existing.get("command_message_id") == update.message.message_id
                )
                if already_started:
                    return
                slide_one_shot_sessions[command_key] = {
                    "target_name": target,
                    "target_user_id": target_user_id,
                    "reply_to_id": reply_to_id,
                    "patterns": patterns,
                    "command_message_id": update.message.message_id,
                }
                old_tasks = slide_tasks[slide_num].pop(chat_id, {})
                for task in old_tasks.values():
                    task.cancel()
                task_key = target_user_id or target.casefold()
                task = asyncio.create_task(
                    slide_reply_loop(chat_id, reply_to_id, patterns, target)
                )
                slide_tasks[slide_num][chat_id] = {task_key: task}
            if not bots or context.bot is bots[0]:
                await update.message.reply_text(
                    f"𝐒ʟɪᴅᴇ{slide_num} 𝐒ᴛᴀʀᴛᴇᴅ 𝐅ᴏʀ {target}."
                )
    slide_cmd.__name__ = f"slide{slide_num}_cmd"
    return slide_cmd


slide1_cmd = _make_slide_cmd(1)
slide2_cmd = _make_slide_cmd(2)
slide3_cmd = _make_slide_cmd(3)
slide4_cmd = _make_slide_cmd(4)


async def _advance_one_shot_slides(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Advance slide1/slide2 once when the configured target sends a message."""
    message = update.effective_message
    user = update.effective_user
    if not message or not user or user.id in our_bot_ids or user.id == OWNER_ID:
        return

    matching = []
    async with slide_session_lock:
        for key, session in slide_one_shot_sessions.items():
            slide_num, chat_id, target_key = key
            if slide_num not in (1, 2) or chat_id != message.chat_id:
                continue
            if session.get("target_user_id") != user.id:
                continue

            event_id = message.message_id
            if session.get("last_message_id") != event_id:
                session["last_message_id"] = event_id
                session["sent_bot_ids"] = set()
                index = session["next_index"]
                session["next_index"] = index + 1
                session["event_pattern"] = session["patterns"][index % len(session["patterns"])]
            bot_key = getattr(context.bot, "id", None) or id(context.bot)
            if bot_key in session["sent_bot_ids"]:
                continue
            session["sent_bot_ids"].add(bot_key)
            matching.append(
                (
                    session["target_name"],
                    session["event_pattern"],
                    session["reply_to_id"],
                )
            )

    for target_name, pattern, reply_to_id in matching:
        await _send_slide_once(
            context.bot,
            message.chat_id,
            target_name,
            pattern,
            message.message_id,
        )


