@only_owner

async def pfp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    args = [arg.strip() for arg in context.args if arg.strip()]

    if args and args[0].lower() in {"menu", "status"}:
        menu = get_pfp_menu(chat_id)
        urls = pfp_urls.get(chat_id, [])
        if urls:
            try:
                first_url = urls[0]
                if isinstance(first_url, str) and first_url.startswith("tgfile:"):
                    return await update.message.reply_photo(photo=first_url[7:], caption=menu)
                if VIDEO_URL_RE.search(str(first_url)):
                    return await update.message.reply_video(video=first_url, caption=menu)
                return await update.message.reply_photo(photo=first_url, caption=menu)
            except Exception as exc:
                logging.warning("PFP menu media failed: %s", exc)
        return await update.message.reply_text(menu)

    if args:
        return await update.message.reply_text("🩶 𝐔sᴇ -apfp 𝐓ᴏ 𝐒ᴀᴠᴇ 𝐏ғᴘs. -pfp 𝐎ɴʟʏ 𝐒ᴛᴀʀᴛs 𝐓ʜᴇ 𝐋ᴏᴏᴘ.")

    if not pfp_urls.get(chat_id):
        return await update.message.reply_text(
            "🩵 𝐔sᴇ 𝐀ᴘғᴘ 𝐓ᴏ 𝐒ᴀᴠᴇ 𝐀ɴᴅ 𝐏ғᴘ 𝐓ᴏ 𝐒ᴛᴀʀᴛ 𝐓ʜᴇ 𝐋ᴏᴏᴘ"
        )

    pfp_loop_stopped.discard(chat_id)
    old_task = photo_loop_tasks.pop(chat_id, None)
    if old_task:
        old_task.cancel()
        await asyncio.gather(old_task, return_exceptions=True)
    photo_loop_tasks[chat_id] = asyncio.create_task(
        photo_loop(chat_id, context.bot)
    )
    await update.message.reply_text(
        f"⚡ 𝐏ғᴘ 𝐋ᴏᴏᴘ 𝐒ᴛᴀʀᴛᴇᴅ · {len(pfp_urls[chat_id])}/{MAX_PHOTOS}\n𝐔sᴇ 𝐒ᴘғᴘ 𝐓ᴏ 𝐒ᴛᴏᴘ 𝐓ʜᴇ 𝐋ᴏᴏᴘ."
    )


def get_pfp_menu(chat_id: int) -> str:
    urls = pfp_urls.get(chat_id, [])
    state = "ACTIVE" if chat_id in photo_loop_tasks else "STOPPED"
    url_lines = [
        f"│ {index}. {url[:42]}{'…' if len(url) > 42 else ''}"
        for index, url in enumerate(urls, start=1)
    ]
    return "\n".join([
        "╭─〔 𝐏𝐅𝐏 〕─╮",
        f"│ {state} · {len(urls)}/{MAX_PHOTOS}",
        *url_lines,
        "│ /pfp start  /apfp save",
        "│ /dpfp <no> /spfp stop",
        "╰────────────╯",
    ])





@only_owner
async def apfp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    stored = pfp_urls.setdefault(chat_id, [])
    reply = update.message.reply_to_message

    # Add a replied photo directly to the PFP loop.
    if reply and reply.photo:
        file_id = reply.photo[-1].file_id
        value = f"tgfile:{file_id}"
        if value not in stored and len(stored) < MAX_PHOTOS:
            stored.append(value)
            return await update.message.reply_text(
                f"⚡ 𝐏ғᴘ 𝐒ᴀᴠᴇᴅ 𝐅ʀᴏᴍ 𝐑ᴇᴘʟʏ· {len(stored)}/{MAX_PHOTOS}"
            )
        return await update.message.reply_text("🩶 𝐓ʜɪs 𝐏ғᴘ 𝐈s 𝐀ʟʀᴇᴀᴅʏ 𝐒ᴀᴠᴇᴅ 𝐎ʀ 𝐋ɪᴍɪᴛ 𝐈s 𝐅ᴜʟʟ.")

    urls = [arg.strip() for arg in context.args if arg.strip()]
    if not urls or not all(PFP_URL_RE.match(url) for url in urls):
        return await update.message.reply_text("🩶 𝐑ᴇᴘʟʏ ᴛᴏ ᴀ 𝐏ʜᴏᴛᴏ ᴡɪᴛʜ -𝐀ᴘғᴘ ᴏʀ ᴜsᴇ -𝐀ᴘғᴘ <𝐇ᴛᴛᴘ(s) 𝐈ᴍᴀɢᴇ/𝐕ɪᴅᴇᴏ 𝐔ʀʟ>")

    added = 0
    for url in urls:
        if url not in stored and len(stored) < MAX_PHOTOS:
            stored.append(url)
            added += 1
    await update.message.reply_text(
        f"⚡ 𝐏ғᴘ 𝐒ᴀᴠᴇᴅ: {added} · 𝐓ᴏᴛᴀʟ {len(stored)}/{MAX_PHOTOS}"
    )


@only_owner
async def dpfp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    stored = pfp_urls.get(chat_id, [])
    if not stored:
        return await update.message.reply_text("🩶 𝐍ᴏ 𝐏ғᴘs 𝐀ʀᴇ 𝐒ᴀᴠᴇᴅ.")

    args = [arg.strip() for arg in context.args if arg.strip()]
    if not args:
        return await update.message.reply_text("🩶 𝐔sᴇ <𝐃ᴘғᴘ> 𝐎ʀ <ɴᴏ> 𝐓ᴏ 𝐃ᴇʟᴇᴛᴇ 𝐓ʜᴀᴛ 𝐏ғᴘ.")

    removed = []
    for arg in args:
        if arg.isdigit():
            idx = int(arg) - 1
            if 0 <= idx < len(stored):
                removed.append(idx)
    if not removed:
        return await update.message.reply_text("🩶 𝐈ɴᴠᴀʟɪᴅ 𝐏ғᴘ 𝐍ᴜᴍʙᴇʀ.")

    for idx in sorted(set(removed), reverse=True):
        stored.pop(idx)
    await update.message.reply_text(
        f"⚡ 𝐏ғᴘ · {len(stored)}/{MAX_PHOTOS} 𝐑ᴇᴍᴀɪɴ"
    )


@only_owner
async def spfp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
