_SERIF_MAP = str.maketrans(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
    "𝐀𝐁𝐂𝐃𝐄𝐅𝐆𝐇𝐈𝐉𝐊𝐋𝐌𝐍𝐎𝐏𝐐𝐑𝐒𝐓𝐔𝐕𝐖𝐗𝐘𝐙"
    ,
)

# Existing configured messages contain several Unicode font alphabets.  Fold
# those alphabets back to plain text before applying the single new font
# system, so old italic/monospace/serif output cannot leak into replies.
_SMALL_REVERSE_MAP = {
    ord(value): key.lower()
    for key, value in zip(
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz",
        "ᴀʙᴄᴅᴇғɢʜɪᴊᴋʟᴍɴᴏᴘǫʀsᴛᴜᴠᴡxʏᴢ",
    )
}


def _plain_for_styling(value: str) -> str:
    import unicodedata

    value = unicodedata.normalize("NFKD", value)
    return value.translate(_SMALL_REVERSE_MAP)


def stylize_alternating_name(name: str) -> str:
    words = _plain_for_styling(name.strip().lstrip("@")).split()
    result = []
    for word in words:
        result.append(stylize_name(word))
    return " ".join(result)


def format_target_name(name: str) -> str:
    """Format a moderation target without the leading @."""
    if not name:
        return "User"
    return stylize_alternating_name(str(name))


# SHIVAM alternating serif/small-caps typography
# Example: 𝐇ʏ 𝐒ɪʀ 𝐇ᴏᴡ 𝐀ʀᴇ 𝐘ᴏᴜ
def stylize_reply_text(value) -> str:
    """Format outgoing reply text as alternating serif / small-caps words.
    Emojis, punctuation and non-Latin characters are preserved.
    """
    if value is None:
        return value
    s = _plain_for_styling(str(value))
    out = []
    word_index = 0
    for line in s.splitlines(keepends=True):
        parts = re.split(r"(\s+)", line)
        for part in parts:
            if not part or part.isspace():
                out.append(part)
                continue
            if re.search(r"[A-Za-z]", part):
                out.append(
                    part.translate(_SERIF_MAP)
                    if word_index % 2 == 0
                    else stylize_name(part)
                )
                word_index += 1
            else:
                out.append(part)
        # keep newline exactly as part of the original whitespace chunks
    return "".join(out)


# Typography is applied only to NC/SPAM command target arguments.


OVER_PFP_URL = "https://files.catbox.moe/g2nklw.jpg"

def _over_target(update: Update, context: ContextTypes.DEFAULT_TYPE):
    reply = update.message.reply_to_message
    if reply and reply.from_user:
        user = reply.from_user
        return " ".join(part for part in (user.first_name, user.last_name) if part).strip() or str(user.id)
    if context.args:
        return context.args[0].lstrip("@")
    return "User"


