@only_owner
async def _sudo_target(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        return update.message.reply_to_message.from_user
    if not context.args:
        return None
    raw = context.args[0]
    try:
        return (await context.bot.get_chat(int(raw))).to_dict()
    except Exception:
        try:
            return await context.bot.get_chat(raw if raw.startswith("@") else f"@{raw}")
        except Exception:
            return None


@only_owner
async def addsudo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = await _sudo_target(update, context)
    if not user:
        return await update.message.reply_text("🩵 𝐑ᴇᴘʟʏ 𝐓ᴏ 𝐀 𝐔sᴇʀ 𝐎ʀ 𝐔sᴇ 𝐀ᴅᴅsᴜᴅᴏ.")
    uid = int(user["id"] if isinstance(user, dict) else user.id)
    username = user.get("username") if isinstance(user, dict) else user.username
    first_name = user.get("first_name", str(uid)) if isinstance(user, dict) else (user.first_name or str(uid))
    name = f"@{username}" if username else first_name
    SUDO_USERS.add(uid)
    SUDO_NAMES[uid] = name
