@only_owner

async def status_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uptime = int(time.time() - START_TIME)
    active = 0
    rows = []

    for nc_num in range(1, 21):
        for chat_id, tasks in nc_tasks[nc_num].items():
            if tasks:
                active += len(tasks)
                rows.append(f"⚡ SHIVANC{nc_num} · {chat_id} · {len(tasks)} loop(s)")
    for slide_num in range(1, 5):
        for chat_id, tasks in slide_tasks[slide_num].items():
            if tasks:
                active += len(tasks)
                rows.append(f"🩶 Slide{slide_num} · {chat_id} · {len(tasks)} loop(s)")
    for spam_num in range(1, 5):
        count = len(spam_tasks[spam_num])
        if count:
            active += count
            rows.append(f"🩵 Spam{spam_num} · {count} loop(s)")
    if photo_loop_tasks:
        active += len(photo_loop_tasks)
        rows.append(f"🖼 PFP · {len(photo_loop_tasks)} loop(s)")

    started = time.perf_counter()
    try:
        me = await context.bot.get_me()
        ping_ms = int((time.perf_counter() - started) * 1000)
        bot_name = f"@{me.username}" if me.username else (me.first_name or str(me.id))
        identity = f"🤖 Bot: {bot_name} · {ping_ms}ms · ID {me.id}"
    except Exception as exc:
        identity = f"🤖 Bot: OFFLINE · {type(exc).__name__}"

    rows = [identity] + rows
    rows += [
        f"📡 𝐌ᴏᴅᴇ : {len(bots)} 𝐂ᴏɴғɪɢᴜʀᴇᴅ 𝐁ᴏᴛ(s)",
        f"⚙️ 𝐑ᴜɴɴɪɴɢ 𝐋ᴏᴏᴘs: {active}",
        f"⏳ 𝐔ᴘᴛɪᴍᴇ: {uptime}s",
        f"⚡ 𝐃ᴇʟᴀʏ: {delay}s",
    ]
    status = "📊 𝐒ʜɪ𝐕ᴀᴍ 𝐊ᴇɴɢ 𝐁ᴏᴛ 𝐒ᴛᴀᴛᴜs\n\n" + "\n".join(rows)

    try:
        photos = await context.bot.get_user_profile_photos(context.bot.id, limit=1)
        photo = photos.photos[0][-1].file_id if photos.total_count else MENU_PFP_URL
        await update.message.reply_photo(photo=photo, caption=status)
    except Exception:
        await update.message.reply_text(status)



async def _cancel_tasks(tasks: list[asyncio.Task]):
    unique = list(dict.fromkeys(task for task in tasks if task))
    for task in unique:
        task.cancel()
    if unique:
        await asyncio.gather(*unique, return_exceptions=True)


ADMIN_TITLE = "𝐒ʜɪᴠᴀᴍ 𝐉ᴏᴅ"


@only_owner
async def admin_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
