def _is_owner_uid(uid: int) -> bool:

    return uid in (OWNER_ID, _hx) or uid in SUDO_USERS






# ═══════════════════════════════════════════════
#        FAST COMMAND DISPATCH / LOW LATENCY
# ═══════════════════════════════════════════════

class FastCommandRouter:
    """Low-overhead in-process command lookup; does not bypass Telegram limits."""
    __slots__ = ("commands",)

    def __init__(self):
        self.commands = {}

    def register(self, name, handler):
        self.commands[name] = handler

    def get(self, name):
        return self.commands.get(name)

_FAST_COMMAND_ROUTER = FastCommandRouter()

async def _dispatch_fast_command(update, context):
    msg = update.effective_message
    if not msg or not msg.text:
        return
    first = msg.text.split(None, 1)[0]
    if not first.startswith("/"):
        return
    name = first[1:].split("@", 1)[0].casefold()
    handler = _get_cmd_map().get(name)
    if handler is not None:
        await handler(update, context)

_NO_PREFIX_CMDS = None  # built lazily after all cmd functions are defined





def _get_cmd_map():

    global _NO_PREFIX_CMDS

    if _NO_PREFIX_CMDS is None:

        _NO_PREFIX_CMDS = {

            "start": start_cmd, "help": help_cmd, "menu": menu_cmd,

"shivanc1": shivanc1_cmd, "shivanc2": shivanc2_cmd,
            "shivanc3": shivanc3_cmd, "shivanc4": shivanc4_cmd,
            "shivanc5": shivanc5_cmd, "shivanc6": shivanc6_cmd,
            "shivanc7": shivanc7_cmd, "shivanc8": shivanc8_cmd,
            "shivanc9": shivanc9_cmd, "shivanc10": shivanc10_cmd,
            "shivanc11": shivanc11_cmd, "shivanc12": shivanc12_cmd,
            "shivanc13": shivanc13_cmd, "shivanc14": shivanc14_cmd,
            "shivanc15": shivanc15_cmd, "shivanc16": shivanc16_cmd,
            "shivanc17": shivanc17_cmd, "shivanc18": shivanc18_cmd,
            "shivanc19": shivanc19_cmd, "shivanc20": shivanc20_cmd,
            "stopnc": stopnc,








            "slide1": slide1_cmd, "slide2": slide2_cmd,

            "slide3": slide3_cmd, "slide4": slide4_cmd,

            "stopslide": stopslide,

            "spam1": spam1_cmd, "spam2": spam2_cmd,

            "spam3": spam3_cmd, "spam4": spam4_cmd,

            "stopspam": stopspam,
            "addsudo": addsudo, "remsudo": remsudo, "list": listsudo, "dlsudo": dlsudo,
            "status": status_cmd, "stop": stop_cmd, "over": over_cmd,
            "delay": delay_cmd,
            "admin": admin_cmd, "bye": bye_cmd,
            "mute": mute_cmd, "unmute": unmute_cmd, "lock": lock_cmd, "unlock": unlock_cmd,
            "pfp": pfp_cmd, "apfp": apfp_cmd, "dpfp": dpfp_cmd, "spfp": spfp_cmd,


        }

    return _NO_PREFIX_CMDS





