# ---------------------------
# MODERATION: lock / unlock / mute / unmute
# ---------------------------
locked_chats = set()
muted_users = defaultdict(set)
muted_admins = defaultdict(set)

async def _resolve_moderation_target(update, context):
    msg = update.effective_message
    chat_id = update.effective_chat.id
    if msg and msg.reply_to_message and msg.reply_to_message.from_user:
        return msg.reply_to_message.from_user
    raw = " ".join(context.args).strip() if context.args else ""
    if not raw:
        return None
    candidate = raw.split()[0].lstrip("@")
    try:
        if candidate.lstrip("-").isdigit():
            member = await context.bot.get_chat_member(chat_id, int(candidate))
            return member.user
        # Telegram usernames can be resolved directly.
        try:
            chat = await context.bot.get_chat("@"+candidate)
            if getattr(chat, "id", None):
                member = await context.bot.get_chat_member(chat_id, chat.id)
                return member.user
        except Exception:
            pass
        wanted = candidate.casefold()
        for a in await context.bot.get_chat_administrators(chat_id):
            u = a.user
            if ((u.username and u.username.casefold() == wanted) or
                (u.first_name and u.first_name.casefold() == wanted)):
                return u
    except Exception:
        pass
    return None

@only_owner
async def mute_cmd(update, context):
    chat_id = update.effective_chat.id
    user = await _resolve_moderation_target(update, context)
    if not user:
        return await update.message.reply_text("❌ 𝐑ᴇᴘʟʏ 𝐓ᴏ 𝐀 𝐔sᴇʀ.")
    if user.id == OWNER_ID or user.id in our_bot_ids or user.id == getattr(context.bot, "id", None):
        return await update.message.reply_text("❌ 𝐓ʜɪs 𝐔sᴇʀ 𝐂ᴀɴ'ᴛ 𝐁ᴇ 𝐌ᴜᴛᴇᴅ.")
    try:
        member = await context.bot.get_chat_member(chat_id, user.id)
        label = format_target_name(" ".join(part for part in (user.first_name, user.last_name) if part) or str(user.id))
        muted_users[chat_id].add(user.id)
        if member.status in ("administrator", "creator"):
            muted_admins[chat_id].add(user.id)
            return await update.message.reply_text(f"🔇 {label} → 𝐌ᴜᴛᴇᴅ.")
        await context.bot.restrict_chat_member(chat_id, user.id, permissions=ChatPermissions(can_send_messages=False))
        await update.message.reply_text(f"🔇 {label} → 𝐌ᴜᴛᴇᴅ.")
    except Exception as e:
        await update.message.reply_text(f"❌ 𝐌ᴜᴛᴇ ғᴀɪʟᴇᴅ: {e}")

@only_owner
async def unmute_cmd(update, context):
    chat_id = update.effective_chat.id
    user = await _resolve_moderation_target(update, context)
    if not user:
        return await update.message.reply_text("❌ 𝐑ᴇᴘʟʏ 𝐓ᴏ 𝐀 𝐔sᴇʀ.")
    try:
        member = await context.bot.get_chat_member(chat_id, user.id)
        muted_users[chat_id].discard(user.id)
        muted_admins[chat_id].discard(user.id)
        if member.status not in ("administrator", "creator"):
            await context.bot.restrict_chat_member(chat_id, user.id, permissions=ChatPermissions(
                can_send_messages=True, can_send_audios=True, can_send_documents=True,
                can_send_photos=True, can_send_videos=True, can_send_video_notes=True,
                can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True,
                can_add_web_page_previews=True))
        label = format_target_name(" ".join(part for part in (user.first_name, user.last_name) if part) or str(user.id))
        await update.message.reply_text(f"🔊 {label} → 𝐔ɴᴍᴜᴛᴇᴅ !")
    except Exception as e:
        await update.message.reply_text(f"❌ 𝐔ɴᴍᴜᴛᴇ ғᴀɪʟᴇᴅ: {e}")

@only_owner
async def lock_cmd(update, context):
    chat_id = update.effective_chat.id
    try:
        locked_chats.add(chat_id)
        # Normal members are actually prevented from sending by Telegram.
        # Admin messages are handled by moderation_guard and deleted instantly.
        await context.bot.set_chat_permissions(chat_id, ChatPermissions(can_send_messages=False))
        await update.message.reply_text("🔒 𝐆ʀᴏᴜᴘ 𝐋ᴏᴄᴋᴇᴅ — .")
    except Exception as e:
        locked_chats.discard(chat_id)
        await update.message.reply_text(f"❌ 𝐋ᴏᴄᴋ ғᴀɪʟᴇᴅ: {e}")

@only_owner
async def unlock_cmd(update, context):
    chat_id = update.effective_chat.id
    try:
        locked_chats.discard(chat_id)
        await context.bot.set_chat_permissions(chat_id, ChatPermissions(
            can_send_messages=True, can_send_audios=True, can_send_documents=True,
            can_send_photos=True, can_send_videos=True, can_send_video_notes=True,
            can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True,
            can_add_web_page_previews=True))
        await update.message.reply_text("🔓 𝐆ʀᴏᴜᴘ 𝐔ɴʟᴏᴄᴋᴇᴅ !")
    except Exception as e:
        await update.message.reply_text(f"❌ 𝐔ɴʟᴏᴄᴋ ғᴀɪʟᴇᴅ: {e}")

async def moderation_guard(update, context):
    msg = update.effective_message
    chat = update.effective_chat
    if not msg or not chat or not msg.from_user or chat.type not in ("group", "supergroup"):
        return
    uid, cid = msg.from_user.id, chat.id
    if uid == OWNER_ID or uid == getattr(context.bot, "id", None) or uid in our_bot_ids:
        return
    try:
        member = await context.bot.get_chat_member(cid, uid)
        is_admin = member.status in ("administrator", "creator")
    except Exception:
        is_admin = False

    is_muted = uid in muted_users.get(cid, set()) or uid in muted_admins.get(cid, set())
    is_locked = cid in locked_chats

    # Admins cannot be Telegram-restricted, so their muted/locked messages are
    # deleted immediately by the bot.
    if is_admin and (is_muted or is_locked):
        try:
            await msg.delete()
        except Exception as exc:
            logging.warning("Could not delete admin moderation message: %s", exc)
        return

    # Normal muted users are already blocked at Telegram permission level. This
    # fallback catches messages arriving before the restriction takes effect.
    if is_muted or is_locked:
        try:
            await msg.delete()
        except Exception:
            pass


async def message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):

    if not update.message:

        return

    chat_id = update.message.chat_id

    msg_id = update.message.message_id

    text = (update.message.text or "").strip()

    sender_id = update.effective_user.id if update.effective_user else None



    # ── No-prefix command dispatch for owners ──

    if sender_id and _is_owner_uid(sender_id) and text and text.startswith("-"):

        parts = text[1:].split()
        if not parts:
            return

        cmd_word = parts[0].lower()

        cmd_map = _get_cmd_map()

        if cmd_word in cmd_map:

            context.args = parts[1:]

            await cmd_map[cmd_word](update, context)

            return

    await _advance_one_shot_slides(update, context)





